#pragma once

// Bayer CFA demosaic executors for nppi_color_conversion.h (package c4):
//   nppiCFAToRGB_32u_C1C3R_Ctx
//   nppiCFAToRGBA_{8u,16u,32u}_C1AC4R[_Ctx]
//
// Host-visible surface: the entry points are declared here and defined in
// nppi_cfa_executor.cu.  The public wrappers are generated by
// mpp_scripts/gen_family.py (mpp_scripts/families/nppi_cfa_to_rgb.json and
// nppi_cfa_to_rgba.json).
//
// Semantics (baseline NVIDIA NPP 13.4, measured on the RTX 5090 and verified
// element-exact by the differential tests):
//   * Bilinear demosaic with 8-bit/16-bit/32-bit integer arithmetic and
//     truncating (floor) divisions.  Base pixels are copied unchanged.
//   * Green at an R/B base pixel uses chroma correlation: the horizontal and
//     vertical R (or B) neighbour pairs at +-2 are compared with the doubled
//     center value (|2*center - (n1+n2)|); the smaller side wins, and an exact
//     tie averages the four cardinal G samples as
//     ((Gleft+Gright)/2 + (Gup+Gdown)/2)/2.
//   * The missing R/B value at the other base colour is the average of the
//     four diagonal samples, paired according to the output row parity:
//     even rows average the two columns (vertical pairs first), odd rows
//     average the two rows (horizontal pairs first), flooring at each step.
//   * Border samples outside oSrcSize are mirrored (-1 -> 1, n -> n-2).
//   * The destination is written from its origin; the oSrcROI width/height
//     fields act as exclusive right/bottom edges (NVIDIA quirk): the number
//     of produced pixels is (width - x) x (height - y).  A zero or negative
//     extent still passes the size checks as long as width == x / height == y,
//     in which case nothing is written.
//   * RGBA variants write the constant nAlpha; the odd destination byte past
//     the ROI (row padding) is never touched.
//   * Validation order: null pointers (NPP_NULL_POINTER_ERROR) ->
//     interpolation mode != NPPI_INTER_UNDEFINED or eGrid outside [0,3]
//     (NPP_BAD_ARGUMENT_ERROR) -> negative ROI origin (NPP_OUT_OFF_RANGE_ERROR)
//     -> non-positive / odd ROI fields (NPP_SIZE_ERROR) -> ROI that ends past
//     oSrcSize (NPP_OUT_OFF_RANGE_ERROR) -> destination step smaller than the
//     produced row (NPP_STEP_ERROR) -> destination step not a whole number of
//     destination pixels (NPP_NOT_EVEN_STEP_ERROR).  Negative steps are
//     accepted as a successful no-op.  NVIDIA does not validate the source
//     step; mcMPP additionally requires nSrcStep >= produced width * sizeof(T)
//     (documented deviation, not covered by goldens).

#include "npp.h"
#include <cuda_runtime.h>

namespace nppi {
namespace cfa {

// 3-channel packed RGB output.
NppStatus cfaToRgb(const Npp8u *pSrc, int nSrcStep, NppiSize oSrcSize, NppiRect oSrcROI, Npp8u *pDst, int nDstStep,
                   NppiBayerGridPosition eGrid, NppiInterpolationMode eInterpolation, cudaStream_t stream);
NppStatus cfaToRgb(const Npp16u *pSrc, int nSrcStep, NppiSize oSrcSize, NppiRect oSrcROI, Npp16u *pDst, int nDstStep,
                   NppiBayerGridPosition eGrid, NppiInterpolationMode eInterpolation, cudaStream_t stream);
NppStatus cfaToRgb(const Npp32u *pSrc, int nSrcStep, NppiSize oSrcSize, NppiRect oSrcROI, Npp32u *pDst, int nDstStep,
                   NppiBayerGridPosition eGrid, NppiInterpolationMode eInterpolation, cudaStream_t stream);

// 4-channel packed RGBA output with a constant alpha value.
NppStatus cfaToRgba(const Npp8u *pSrc, int nSrcStep, NppiSize oSrcSize, NppiRect oSrcROI, Npp8u *pDst, int nDstStep,
                    NppiBayerGridPosition eGrid, NppiInterpolationMode eInterpolation, Npp8u nAlpha,
                    cudaStream_t stream);
NppStatus cfaToRgba(const Npp16u *pSrc, int nSrcStep, NppiSize oSrcSize, NppiRect oSrcROI, Npp16u *pDst, int nDstStep,
                    NppiBayerGridPosition eGrid, NppiInterpolationMode eInterpolation, Npp16u nAlpha,
                    cudaStream_t stream);
NppStatus cfaToRgba(const Npp32u *pSrc, int nSrcStep, NppiSize oSrcSize, NppiRect oSrcROI, Npp32u *pDst, int nDstStep,
                    NppiBayerGridPosition eGrid, NppiInterpolationMode eInterpolation, Npp32u nAlpha,
                    cudaStream_t stream);

}  // namespace cfa
}  // namespace nppi
